/**
 * Every HTTP request the proxy answered, and the ones it is answering now, in memory, for the
 * terminal console's Requests table: the method, the path, the status and when.
 *
 * @remarks
 * {@link requestLogMiddleware} adds a request when it arrives and ends it when its answer is
 * ready: for a stream, when its headers are, so the console takes a chat stream's true end from
 * the chat requests (`active-requests.ts`), joined by the request ID (generated by the proxy, so
 * unique).
 *
 * The middleware runs before proxy auth, so anyone who can reach the port can add entries. As in
 * `active-requests.ts`, client errors (4xx: auth, size, validation, unknown paths) are kept apart
 * from the rest, each list with its own bound, so a flood of them can't push out the requests that
 * did something. A health check shows only once it has failed: monitors poll it every few seconds,
 * so one in flight is not listed and tells no listener, and one answered with a 2xx is not kept,
 * as the request log puts those lines at debug for the same reason. No HTTP route serves this.
 *
 * An entry holds the request's ID, method, path (without its query, where a caller could put a
 * secret, and cut at {@link PATH_KEPT} characters), status and timings: never a header, a body, or
 * a credential.
 *
 * @packageDocumentation
 */

import { proxyLogger } from '@proxy/logging'
import { FINISHED_KEPT, REJECTED_KEPT } from '@proxy/server/active-requests'
import {
  HTTP_BAD_REQUEST,
  HTTP_INTERNAL_SERVER_ERROR,
  HTTP_MULTIPLE_CHOICES
} from '@proxy/server/http-status'
import { isHealthPath } from '@proxy/server/middleware'
import type { ProxyEnv } from '@proxy/server/types'
import type { MiddlewareHandler } from 'hono'

/**
 * The longest path kept, in characters; a longer one is cut with `…`. Every route's path is far
 * shorter: this bounds what a caller who sends a long URL can make the proxy hold.
 */
export const PATH_KEPT = 256

/** Logger for a listener that throws. */
const httpRequestsLogger = proxyLogger('server', 'http')

/** One HTTP request, in flight or answered. */
export interface HttpRequest {
  /** Its place in the order the requests arrived: a view pinned to one stays on it. */
  readonly sequence: number
  /** The proxy's request ID (`X-Request-Id`). */
  readonly requestId: string
  readonly method: string
  /** The path, without the query. */
  readonly path: string
  /** When it arrived, in milliseconds since the epoch. */
  readonly startedAt: number
  /** The status it was answered with; `undefined` while it is in flight. */
  readonly status: number | undefined
  /** When its answer was ready (a stream's headers); `undefined` while it is in flight. */
  readonly endedAt: number | undefined
}

/** The requests in flight, by their place in the order. */
const inFlight = new Map<number, HttpRequest>()
/** The answered requests that were not client errors, oldest first, at most {@link FINISHED_KEPT}. */
const answered: HttpRequest[] = []
/** The client errors, oldest first, at most {@link REJECTED_KEPT}. */
const clientErrors: HttpRequest[] = []
/** The next request's place in the order. */
let nextSequence = 0
/** Who is told after each change. */
const listeners = new Set<() => void>()

/**
 * Tells every listener the requests changed. A listener that throws is logged and skipped: the
 * request that caused the change must not fail for it.
 */
function notify(): void {
  for (const listener of listeners) {
    try {
      listener()
    } catch (error) {
      httpRequestsLogger.warn('An HTTP requests listener threw: {errorName}', {
        errorName: error instanceof Error ? error.name : typeof error
      })
    }
  }
}

/**
 * Adds a request as it arrives.
 *
 * @param start - its ID, method and path
 * @param start.requestId - the proxy's request ID
 * @param start.method - the HTTP method
 * @param start.path - the path, without the query; cut at {@link PATH_KEPT} characters
 * @param now - the current time; `Date.now()` by default
 * @returns its place in the order, to end it with
 */
export function beginHttpRequest(
  start: { readonly requestId: string; readonly method: string; readonly path: string },
  now: number = Date.now()
): number {
  const sequence = nextSequence
  nextSequence += 1
  const path = start.path.length > PATH_KEPT ? `${start.path.slice(0, PATH_KEPT)}…` : start.path
  inFlight.set(sequence, {
    ...start,
    path,
    sequence,
    startedAt: now,
    status: undefined,
    endedAt: undefined
  })
  // A health check in flight isn't listed: telling the listeners would only redraw for nothing.
  if (!isHealthPath(path)) notify()
  return sequence
}

/**
 * Ends a request with its answer's status, keeping it in its list, dropping that list's oldest
 * past its bound. A health check answered with a 2xx is dropped instead.
 *
 * @param sequence - its place in the order, from {@link beginHttpRequest}
 * @param status - the status it was answered with
 * @param now - the current time; `Date.now()` by default
 */
export function endHttpRequest(sequence: number, status: number, now: number = Date.now()): void {
  const request = inFlight.get(sequence)
  if (request === undefined) return
  inFlight.delete(sequence)
  // A health check that passed was never listed, so nothing changed for the listeners.
  if (isHealthPath(request.path) && status < HTTP_MULTIPLE_CHOICES) return
  // 5xx answers are kept with the others: the proxy failed, not the client.
  const clientError = status >= HTTP_BAD_REQUEST && status < HTTP_INTERNAL_SERVER_ERROR
  const [kept, bound] = clientError ? [clientErrors, REJECTED_KEPT] : [answered, FINISHED_KEPT]
  kept.push({ ...request, status, endedAt: now })
  if (kept.length > bound) kept.shift()
  notify()
}

/**
 * Returns a snapshot of the requests kept and in flight.
 *
 * @returns them, in the order they arrived, oldest first
 */
export function httpRequests(): readonly HttpRequest[] {
  const listedInFlight = [...inFlight.values()].filter((request) => !isHealthPath(request.path))
  return [...answered, ...clientErrors, ...listedInFlight].toSorted(
    (left, right) => left.sequence - right.sequence
  )
}

/**
 * Subscribes to changes.
 *
 * @param listener - called after every change; read {@link httpRequests}
 * @returns a function that unsubscribes the listener
 */
export function onHttpRequestsChange(listener: () => void): () => void {
  listeners.add(listener)
  return () => {
    listeners.delete(listener)
  }
}

/**
 * Creates the middleware that lists every request for the console: added as it arrives, ended
 * with its status when its answer is ready. Registered after the request ID middleware, whose ID
 * it reads.
 *
 * @remarks
 * Hono turns a handler's error into an answer before this middleware sees it; should one escape
 * anyway, the request still ends, as a 500, so none stays in flight forever.
 *
 * @returns the middleware
 */
export function requestLogMiddleware(): MiddlewareHandler<ProxyEnv> {
  return async (context, next) => {
    const sequence = beginHttpRequest({
      requestId: context.get('requestId'),
      method: context.req.method,
      path: context.req.path
    })
    let status = HTTP_INTERNAL_SERVER_ERROR
    try {
      await next()
      status = context.res.status
    } finally {
      endHttpRequest(sequence, status)
    }
  }
}
